public class VipDiscount : DiscountPolicy
{
    public override decimal Apply(decimal amount)
    {
        if (amount < 0) throw new ArgumentOutOfRangeException(nameof(amount));
        return amount >= 100m ? amount * 0.9m : amount;
    }
